    // Your implementation here
}
```

You can use the following API endpoint to make a POST request to detect the language:

Endpoint: `https://translation.googleapis.com/language/translate/v2/detect`
Method: POST
Request Body: 
```json
{
  "q": "YOUR_TEXT_HERE"
}
```
Request Headers:
- `Content-Type: application/json`
- `Authorization: Bearer YOUR_API_KEY`

The API response will be in JSON format and will contain the detected language code in the `language` field.

Your function should handle the HTTP request to the Google Translate API, extract the detected language code from the API response, and return it.

### Solution:
```swift
import Foundation

func detectLanguage(text: String) -> String {
    let apiKey = "YOUR_API_KEY"  // Replace with your actual API key
    let endpoint = "https://translation.googleapis.com/language/translate/v2/detect"

    guard let url = URL(string: endpoint) else {
        fatalError("Invalid API endpoint")
    }

    var request = URLRequest(url: url)
    request.httpMethod = "POST"
    request.setValue("application/json", forHTTPHeaderField: "Content-Type")
    request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")

    let requestBody = ["q": text]
    let jsonData = try! JSONSerialization.data(withJSONObject: requestBody)
    request.httpBody = jsonData

    let semaphore = DispatchSemaphore(value: 0)
    var detectedLanguageCode = ""

    let task = URLSession.shared.dataTask(with: request) { data, response, error in
        defer { semaphore.signal() }

        guard let data = data, error == nil else {
            print("Error: \(error?.localizedDescription ?? "Unknown error")")
            return
        }

        do {
            if let json = try JSONSerialization.jsonObject(with: data) as? [String: Any],
               let data = json["data"] as? [String: Any],
               let detections = data["detections"] as? [[String: Any]],
               let detection = detections.first,
               let language = detection["language"] as? String {
                detectedLanguageCode = language
            }
        } catch {
            print("Error parsing JSON: \(error.localizedDescription)")
        }
    }

    task.resume()
    semaphore.wait()

    return detectedLanguageCode
}
```

Please note that the `YOUR_API_KEY` placeholder in the solution should be replaced with your actual Google Translate API key for the function to work correctly. Additionally, error handling and proper response parsing should be considered for production-level code.

