    pub fn retry_count(mut self, count: u32) -> Self {
        self.retry_count = count;
        self
    }

    pub fn build(self) -> HttpClient {
        HttpClient {
            autologin: self.autologin,
            retry_count: self.retry_count,
            client: Client::new(),
        }
    }
}

pub struct HttpClient {
    autologin: String,
    retry_count: u32,
    client: Client,
}

impl HttpClient {
    fn send_request(&self, path: &str, body: Option<String>) -> Result<Response, Error> {
        let mut retry = 0;
        loop {
            let mut request = self.client.request(reqwest::Method::GET, &format!("{}{}", ENDPOINT, path));
            if let Some(body) = body {
                request = request.body(body);
            }
            let response = request
                .header("autologin", &self.autologin)
                .send();

            match response {
                Ok(res) if res.status().is_success() => return Ok(res),
                Ok(res) if retry < self.retry_count => {
                    retry += 1;
                    continue;
                }
                Ok(res) => return Err(Error::new(reqwest::Error::Status(res.status()))),
                Err(e) => return Err(e),
            }
        }
    }

    pub fn send_get_request(&self, path: &str) -> Result<String, Error> {
        let mut response = self.send_request(path, None)?;
        response.text()
    }

    pub fn send_post_request(&self, path: &str, body: &str) -> Result<String, Error> {
        let mut response = self.send_request(path, Some(body.to_string()))?;
        response.text()
    }
}
```

In the solution, we complete the implementation of the HTTP client in Rust by adding the required methods and logic to handle authentication and retries. We use the `reqwest` crate for making HTTP requests and handling responses. The `HttpClient` struct contains the autologin token, retry count, and a reqwest client instance. The `send_request` method handles the actual HTTP request, including authentication and retry logic. The `send_get_request` and `send_post_request` methods utilize the `send_request` method to send GET and POST requests, respectively, and return the response body as a string or an error.

