```python
import requests
from functools import wraps
from flask import jsonify, request

def check_recaptcha(view_func):
    @wraps(view_func)
    def decorated_function(*args, **kwargs):
        recaptcha_token = request.args.get('recaptcha_token')
        if recaptcha_token:
            # Replace 'YOUR_RECAPTCHA_SECRET_KEY' with your actual reCAPTCHA secret key
            response = requests.post('https://www.google.com/recaptcha/api/siteverify', 
                                     data={'secret': 'YOUR_RECAPTCHA_SECRET_KEY', 'response': recaptcha_token})
            result = response.json()
            if result['success']:
                return view_func(*args, **kwargs)
            else:
                return jsonify({'error': 'Invalid reCAPTCHA token'})
        else:
            return jsonify({'error': 'reCAPTCHA token missing'})
    return decorated_function

@app.route('/protected', methods=['GET'])
@check_recaptcha
def protected_view():
    return jsonify({'message': 'Access granted to protected view'})
