class Router {
    private $routes = [];

    public function registerGet($url, $handler) {
        $this->register($url, 'GET', $handler);
    }

    public function registerPost($url, $handler) {
        $this->register($url, 'POST', $handler);
    }

    public function register($url, $method, $handler) {
        $this->routes[$method][$url] = $handler;
    }

    public function dispatch($url, $method) {
