        return jsonify({'message': 'Drawing not found'}), 404

# Endpoint for updating the details of a drawing file
@app.route('/drawings/<int:drawing_id>', methods=['PUT'])
def update_drawing(drawing_id):
    drawing = Drawing.query.get(drawing_id)
    if drawing:
        data = request.json
        drawing.name = data['name']
        drawing.file_path = data['file_path']
        db.session.commit()
        return jsonify({'message': 'Drawing updated successfully'})
    else:
        return jsonify({'message': 'Drawing not found'}), 404

# Endpoint for deleting a drawing file
@app.route('/drawings/<int:drawing_id>', methods=['DELETE'])
def delete_drawing(drawing_id):
    drawing = Drawing.query.get(drawing_id)
    if drawing:
        db.session.delete(drawing)
        db.session.commit()
        return jsonify({'message': 'Drawing deleted successfully'})
    else:
        return jsonify({'message': 'Drawing not found'}), 404

# Endpoint for retrieving all completed drawings
@app.route('/drawings/completed', methods=['GET'])
def get_completed_drawings():
    completed_drawings = Drawing.query.filter_by(completed=True).all()
    drawings = [{'id': drawing.id, 'name': drawing.name, 'file_path': drawing.file_path} for drawing in completed_drawings]
    return jsonify(drawings)

# Endpoint for retrieving all work-in-progress drawings
@app.route('/drawings/work-in-progress', methods=['GET'])
def get_work_in_progress_drawings():
    work_in_progress_drawings = Drawing.query.filter_by(completed=False).all()
    drawings = [{'id': drawing.id, 'name': drawing.name, 'file_path': drawing.file_path} for drawing in work_in_progress_drawings]
    return jsonify(drawings)

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
```
