def simulate_rest_call(method, endpoint, payload=None):
    if payload is not None:
        print(f"Making a {method} request to {endpoint} with payload: {payload}")
    else:
        print(f"Making a {method} request to {endpoint} with no payload")

    if method == "GET":
        return {'status': 200, 'message': 'Success'}
    elif method == "POST":
        return {'status': 201, 'message': 'Created'}
    elif method == "PUT":
        return {'status': 204, 'message': 'Updated'}
    elif method == "DELETE":
        return {'status': 204, 'message': 'Deleted'}
    else:
        return {'status': 400, 'message': 'Bad Request'}
