```

Parameters:
- `grantType`: A string representing the grant type for authentication.
- `resourceId`: A string representing the resource ID for authentication.
- `clientId`: A string representing the client ID for authentication.
- `username`: A string representing the username for authentication.
- `password`: A string representing the password for authentication.
- `tokenEndPoint`: A string representing the token endpoint URL.
- `requestType`: A string representing the HTTP request type (e.g., "POST").
- `contentType`: A string representing the content type for the request.
- `completion`: A closure that takes a `Result` object with a string for success and an error for failure.

You need to complete the `authenticateUser` function to construct the authentication request, send it to the token endpoint, and handle the response. The completion closure should be called with the authentication result or an error.

### Solution:
```swift
func authenticateUser(grantType: String, resourceId: String, clientId: String, username: String, password: String, tokenEndPoint: String, requestType: String, contentType: String, completion: @escaping (Result<String, Error>) -> Void) {
    let authRequest = NSMutableURLRequest()
    let bodyString = "grant_type=\(grantType)&resource=\(resourceId)&client_id=\(clientId)&username=\(username)&password=\(password)"

    authRequest.url = URL(string: tokenEndPoint)
    authRequest.httpMethod = requestType
    authRequest.setValue(contentType, forHTTPHeaderField: "Content-Type")
    authRequest.httpBody = bodyString.data(using: String.Encoding.utf8)

    let session = URLSession.shared
    let task = session.dataTask(with: authRequest as URLRequest, completionHandler: { (data: Data?, response: URLResponse?, error: Error?) in
        if let error = error {
            completion(.failure(error))
        } else if let data = data {
            // Parse the data to extract the authentication result
            if let result = String(data: data, encoding: .utf8) {
                completion(.success(result))
            } else {
                let parsingError = NSError(domain: "ParsingError", code: 0, userInfo: [NSLocalizedDescriptionKey: "Failed to parse authentication result"])
                completion(.failure(parsingError))
            }
        } else {
            let unknownError = NSError(domain: "UnknownError", code: 0, userInfo: [NSLocalizedDescriptionKey: "Unknown error occurred"])
            completion(.failure(unknownError))
        }
    })
    task.resume()
}
```

