```python
from rest_framework import viewsets
from rest_framework.response import Response
from rest_framework import status
from .models import Group  # Assuming the Group model is defined in a separate file

class GroupViewSet(viewsets.ViewSet):
    def retrieve(self, request, id=None):
        try:
            group = Group.objects.get(id=id)
            # Assuming GroupSerializer is defined for serializing Group model
            serializer = GroupSerializer(group)
            return Response(serializer.data, status=status.HTTP_200_OK)
        except Group.DoesNotExist:
            return Response({"error": "Group not found"}, status=status.HTTP_404_NOT_FOUND)

    def update(self, request, id=None):
        try:
            group = Group.objects.get(id=id)
            # Assuming GroupSerializer is defined for deserializing Group model
            serializer = GroupSerializer(group, data=request.data)
            if serializer.is_valid():
                serializer.save()
                return Response(serializer.data, status=status.HTTP_200_OK)
            return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)
        except Group.DoesNotExist:
            return Response({"error": "Group not found"}, status=status.HTTP_404_NOT_FOUND)

    def destroy(self, request, id=None):
        try:
