using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Web.Http;
using Alan.ApiDocumentation.Models;

namespace Alan.ApiDocumentation.Demonstration.Controllers
{
    public class BooksController : ApiController
    {
        private static List<Book> _books = new List<Book>
        {
            new Book { Id = 1, Title = "The Great Gatsby", Author = "F. Scott Fitzgerald", Genre = "Fiction" },
            new Book { Id = 2, Title = "To Kill a Mockingbird", Author = "Harper Lee", Genre = "Fiction" }
        };

        // GET /api/books
        public IHttpActionResult GetBooks()
        {
            return Ok(_books);
        }

        // GET /api/books/{id}
        public IHttpActionResult GetBook(int id)
        {
            var book = _books.FirstOrDefault(b => b.Id == id);
            if (book == null)
            {
                return NotFound();
            }
            return Ok(book);
        }

        // POST /api/books
        public IHttpActionResult PostBook(Book book)
        {
            book.Id = _books.Max(b => b.Id) + 1;
            _books.Add(book);
            return Created(Request.RequestUri + "/" + book.Id, book);
        }

        // PUT /api/books/{id}
        public IHttpActionResult PutBook(int id, Book book)
        {
            var existingBook = _books.FirstOrDefault(b => b.Id == id);
            if (existingBook == null)
            {
                return NotFound();
            }
            existingBook.Title = book.Title;
            existingBook.Author = book.Author;
            existingBook.Genre = book.Genre;
            return StatusCode(HttpStatusCode.NoContent);
        }

        // DELETE /api/books/{id}
        public IHttpActionResult DeleteBook(int id)
        {
            var book = _books.FirstOrDefault(b => b.Id == id);
            if (book == null)
            {
                return NotFound();
            }
            _books.Remove(book);
            return StatusCode(HttpStatusCode.NoContent);
        }
    }
}
```

