from werkzeug.exceptions import NotFound, BadRequest
from uuid import uuid4

app = Flask(__name__)
CORS(app)

student_cards = []

class StudentCard:
    def __init__(self, name, student_id, balance):
        self.id = str(uuid4())
        self.name = name
        self.student_id = student_id
        self.balance = balance

