    #[structopt(parse(from_os_str))]
    directory: PathBuf,
}

fn main() {
    if let Err(e) = run() {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}

fn run() -> Result<(), failure::Error> {
    let args = Cli::from_args();
    let (tx, rx) = channel();
    let mut watcher = watcher(tx, Duration::from_secs(1))?;
    watcher.watch(&args.directory, RecursiveMode::Recursive)?;

    let build_route = warp::path("build")
        .and(warp::post())
        .map(|| {
            match buildcmd::execute_build_command() {
                Ok(_) => Response::builder()
                    .status(StatusCode::OK)
                    .body("Build triggered successfully".into())
                    .unwrap(),
                Err(e) => Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .body(format!("Failed to trigger build: {}", e))
                    .unwrap(),
            }
        });

    let routes = build_route.with(warp::log("build"));

    tokio::spawn(warp::serve(routes).run(([127, 0, 0, 1], 3030));

    loop {
        match rx.recv() {
            Ok(event) => {
                if let notify::DebouncedEvent::Write(_) = event {
                    match buildcmd::execute_build_command() {
                        Ok(_) => println!("Build triggered due to file change"),
                        Err(e) => eprintln!("Failed to trigger build: {}", e),
                    }
                }
            }
            Err(e) => eprintln!("Watcher error: {}", e),
        }
    }
}
```

This solution provides a Rust program that monitors a directory for file changes, triggers a build process when a file is modified, and exposes a REST API endpoint for manual build triggering. The program uses the `notify` crate for file watching, the `warp` crate for the REST API, and the provided modules for build command execution and error handling.

