### Solution:
```rust
use reqwest;

struct APIClient {
    base_url: String,
}

impl APIClient {
    fn new(base_url: &str) -> APIClient {
        APIClient {
            base_url: base_url.to_string(),
        }
    }

    fn fetch_application_token(&self, user_id: &str) -> Result<Option<String>, reqwest::Error> {
        let url = format!("{}/users/{}/token", self.base_url, user_id);
        let response = reqwest::blocking::get(&url)?;

        if response.status().is_success() {
            let body = response.text()?;
            if let Some(token) = serde_json::from_str::<serde_json::Value>(&body)
                .ok()
                .and_then(|json| json["application_token"].as_str())
            {
                Ok(Some(token.to_string()))
            } else {
                Ok(None)
            }
        } else {
            Err(reqwest::Error::new(reqwest::Error::Kind::Status, "Request failed"))
        }
    }
}

fn main() {
    let client = APIClient::new("https://api.example.com");
    match client.fetch_application_token("user123") {
        Ok(Some(token)) => println!("Application token: {}", token),
        Ok(None) => println!("No application token found for the user"),
        Err(err) => eprintln!("Error: {}", err),
    }
}
```

