using System;
using System.Net.Http;
using System.Threading.Tasks;

public class ApiHandler
{
    private HttpClient httpClient;

    public ApiHandler()
    {
        httpClient = new HttpClient();
    }

    public async Task<HttpResponseMessage> SendApiRequest(string apiEndpoint)
    {
        // Send an API request to the specified endpoint
        HttpResponseMessage response = await httpClient.GetAsync(apiEndpoint);
        return response;
    }

    protected bool CheckIfErrorStatusCode(HttpResponseMessage response)
    {
        // Check if the response indicates an error status code
        return !response.IsSuccessStatusCode;
    }
}
