```rust
extern crate url;
use std::io::Read;
use url::Url;
use serde::{Deserialize, Serialize};

pub mod bittrex {
    #[derive(Debug, Deserialize)]
    struct MarketSummary {
        symbol: String,
        high: f64,
        low: f64,
        last: f64,
        volume: f64,
    }

    pub fn get_market_summary(trading_pair: &str) -> Result<MarketSummary, String> {
        let api_url = format!("https://api.bittrex.com/api/v1.1/public/getmarketsummary?market={}", trading_pair);
        let url = Url::parse(&api_url).map_err(|e| format!("Failed to parse URL: {}", e))?;

        let mut response = reqwest::get(url).map_err(|e| format!("Failed to send request: {}", e))?;
        let mut body = String::new();
        response.read_to_string(&mut body).map_err(|e| format!("Failed to read response: {}", e))?;

        let json: serde_json::Value = serde_json::from_str(&body).map_err(|e| format!("Failed to parse JSON: {}", e))?;
        let market_summary: MarketSummary = serde_json::from_value(json["result"][0].clone()).map_err(|e| format!("Failed to deserialize market summary: {}", e))?;

        Ok(market_summary)
    }
