    {
        _driverRepository.Create(driver);
        return CreatedAtAction(nameof(GetDriver), new { id = driver.Id }, driver);
    }

    [HttpPut("{id}")]
    public IActionResult UpdateDriver(int id, [FromBody] Driver driver)
    {
        var existingDriver = _driverRepository.GetById(id);
        if (existingDriver == null) return NotFound();
        driver.Id = id; // Ensure the ID in the request body matches the endpoint parameter
        _driverRepository.Update(driver);
        return NoContent();
    }

    [HttpDelete("{id}")]
    public IActionResult DeleteDriver(int id)
    {
        var existingDriver = _driverRepository.GetById(id);
        if (existingDriver == null) return NotFound();
        _driverRepository.Delete(id);
        return NoContent();
    }
}
