```java
import javax.ws.rs.*;
import javax.ws.rs.core.Response;
import static javax.ws.rs.core.Response.Status.*;

@Path("/modules")
public class ModuleManager {
    private Map<String, ModuleDescriptor> moduleDescriptors = new HashMap<>();

    @GET
    @Path("/{module}")
    public Response getModuleDescription(@PathParam("module") String module) {
        ModuleDescriptor md = moduleDescriptors.get(module);
        if (md == null) {
            return Response.status(NOT_FOUND).build();
        }
        return Response.ok(md, "application/json").build();
    }

    @PUT
    @Path("/{module}")
    @Consumes("application/json")
    public Response updateModuleDescriptor(@PathParam("module") String module, ModuleDescriptor newDescriptor) {
        if (moduleDescriptors.containsKey(module)) {
            moduleDescriptors.put(module, newDescriptor);
            return Response.ok().build();
        } else {
            return Response.status(NOT_FOUND).build();
        }
    }

    // Other methods for managing module descriptors
}

class ModuleDescriptor {
    private String moduleName;
    private String description;
    private String version;

    // Constructors, getters, and setters
}
```

