```php
class HTTPServer {
    public function __construct(
        public ResponseInterface $response
    ) {}

    public function handle(Request $request): ResponseInterface {
        if ($request->getMethod() === 'GET') {
            return new HTTPResponse(200, 'OK', 'This is a GET request response');
        } elseif ($request->getMethod() === 'POST') {
            return new HTTPResponse(200, 'OK', 'This is a POST request response');
        } else {
            return new HTTPResponse(400, 'Bad Request', 'Unsupported request method');
        }
    }
}

class HTTPResponse implements ResponseInterface {
    private int $statusCode;
    private string $statusText;
    private string $content;

    public function __construct(int $statusCode, string $statusText, string $content) {
        $this->statusCode = $statusCode;
        $this->statusText = $statusText;
        $this->content = $content;
    }

    public function getContent(): string {
        return $this->content;
    }

    public function getStatusCode(): int {
        return $this->statusCode;
    }
}

class Request {
    private string $method;

    public function __construct(string $method) {
        $this->method = $method;
    }

    public function getMethod(): string {
        return $this->method;
    }
}
```

