```python
import requests

class Events:
    def __init__(self, api_key):
        self.api_key = api_key
        self.base_url = "https://api.yelp.com/v3/events"

    def get(self, event_id, locale=None):
        headers = {"Authorization": f"Bearer {self.api_key}"}
        params = {"locale": locale} if locale else {}
        url = f"{self.base_url}/{event_id}"
        response = requests.get(url, headers=headers, params=params)
        return response.json()

    def search(self, location, categories=None, start_date=None, end_date=None):
        headers = {"Authorization": f"Bearer {self.api_key}"}
        params = {"location": location}
        if categories:
            params["categories"] = categories
        if start_date:
            params["start_date"] = start_date
        if end_date:
            params["end_date"] = end_date
        response = requests.get(self.base_url, headers=headers, params=params)
        return response.json()
```

