The Fibonacci sequence is defined as follows:
- F(0) = 0
- F(1) = 1
- F(n) = F(n-1) + F(n-2) for n > 1

Your Dockerfile should expose the service on port 8080 and the service should respond to HTTP requests with the Fibonacci number for the given input.

### Solution:
Dockerfile:
```Dockerfile
# Use the official .NET Core SDK image
FROM mcr.microsoft.com/dotnet/core/sdk:3.1 AS build-env

# Set the working directory in the container
WORKDIR /app

# Copy the project file and restore any dependencies
COPY ./Fibon.Service/*.csproj ./
RUN dotnet restore

# Copy the remaining source code
COPY ./Fibon.Service/ ./

# Build the application
RUN dotnet publish -c Release -o out

# Generate runtime image
FROM mcr.microsoft.com/dotnet/core/aspnet:3.1
WORKDIR /app
COPY --from=build-env /app/out .
EXPOSE 8080
ENTRYPOINT ["dotnet", "Fibon.Service.dll"]
```

Fibonacci Service Code (Fibon.Service/Fibon.Service.cs):
```csharp
using System;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;

namespace Fibon.Service
{
    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseRouting();
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapGet("/{number}", async context =>
                {
                    if (int.TryParse(context.Request.RouteValues["number"] as string, out int n))
                    {
                        int result = CalculateFibonacci(n);
                        await context.Response.WriteAsync(result.ToString());
                    }
                    else
                    {
                        context.Response.StatusCode = 400;
                        await context.Response.WriteAsync("Invalid input");
                    }
                });
            });
        }

        private int CalculateFibonacci(int n)
        {
            if (n == 0) return 0;
            if (n == 1) return 1;
            int a = 0, b = 1, c = 0;
            for (int i = 2; i <= n; i++)
            {
                c = a + b;
                a = b;
                b = c;
            }
            return c;
        }
    }
}
```

