### Solution:
```python
from flask import Flask, request
from flask_restful import Resource, Api

app = Flask(__name__)

# Mock database for demonstration purposes
people_db = {}
companies_db = {}

class PersonResource(Resource):
    def get(self, username):
        if username in people_db:
            return people_db[username], 200
        else:
            return "Person not found", 404

    def post(self):
        data = request.get_json()
        username = data.get('username')
        # Check if the person already exists
        if username in people_db:
            return "Person already exists", 400
        else:
            people_db[username] = data
            return "Person created successfully", 201

    def put(self, username):
        if username in people_db:
            data = request.get_json()
            people_db[username] = data
            return "Person updated successfully", 200
        else:
            return "Person not found", 404

    def delete(self, username):
        if username in people_db:
            del people_db[username]
            return "Person deleted successfully", 200
        else:
            return "Person not found", 404

class CompanyResource(Resource):
    def get(self, name):
        if name in companies_db:
            return companies_db[name], 200
        else:
            return "Company not found", 404

def get_endpoints(app):
    api = Api(app)
    api.add_resource(PersonResource, '/people', '/people/<string:username>')
    api.add_resource(CompanyResource, '/company/<string:name>')
    return api

if __name__ == '__main__':
    get_endpoints(app)
    app.run()
```

