class Router {
    private $routes = [];

    public function get($route, $controllerMethod) {
        $this->routes['GET'][$route] = $controllerMethod;
    }

    public function post($route, $controllerMethod) {
        $this->routes['POST'][$route] = $controllerMethod;
    }

    public function dispatch($httpMethod, $uri) {
        if (isset($this->routes[$httpMethod][$uri])) {
            $controllerMethod = $this->routes[$httpMethod][$uri];
            list($controller, $method) = explode(':', $controllerMethod);
            $this->callControllerMethod($controller, $method);
        } else {
            echo "404 Not Found";
        }
    }

