extern crate actix_web;
extern crate sysinfo;

use actix_web::{web, App, HttpServer, HttpResponse, Responder};
use sysinfo::{System, SystemExt};

fn system_info_handler() -> impl Responder {
    let mut sys = System::new();
    sys.refresh_all();

    let os = sys.get_operating_system().unwrap_or("Unknown".to_string());
    let kernel_version = sys.get_kernel_version().unwrap_or("Unknown".to_string());
    let cpu_usage = sys.get_global_processor_info().get_cpu_usage();
