        "operating_system": os,
        "kernel_version": kernel_version,
        "cpu_usage_percent": cpu_usage,
        "memory_usage_bytes": memory_usage,
        "total_disk_space_bytes": total_disk_space,
    });

    HttpResponse::Ok().json(system_info_json)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .service(web::resource("/system-info").route(web::get().to(system_info_handler)))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
