use App\Models\Supervisor;
use App\Models\Project;
use Illuminate\Http\Request;

class ProjectNamesController extends Controller
{
    public function __invoke(Request $request)
    {
        $token = $request->get('api_token'); // Extract the API token from the request
        $supervisor = Supervisor::where('api_token', $token)->first(); // Find the supervisor by API token

        if ($supervisor) {
            $projects = Project::where('supervisor_id', $supervisor->id)->select('id', 'title')->get(); // Retrieve projects associated with the supervisor
            $projects->makeHidden(['tags', 'type_name', 'vacant_places', 'state_name', 'supervisor_name']); // Remove specific fields from the project data
            return response()->json($projects, 200); // Return the project data as JSON response
